"""Build the standalone HTML from the canonical tree, inventory and criteria; no network."""
import json,hashlib
from pathlib import Path
P=Path(__file__).resolve().parent

def payload(path):
    return json.dumps(json.loads((P/path).read_text()),ensure_ascii=False,separators=(',',':')).replace('</','<\\/').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
css=(P/'styles.css').read_text();js=(P/'viewer.js').read_text()
bookmarks=[('Q00','Inicio · pregunta raíz'),('F00','Fundaciones · my-skills'),('ENV00','Medio y alcance'),('D00','Identidad y cobertura'),('ART00','Dirección de arte'),('T00','Tipografía'),('L00','Layout'),('R01','Catálogo por requisito'),('R11','Lista y arrastre'),('M03','Movimiento'),('A10','Reutilización'),('QA01','Revisión de conjunto'),('GOV00','Cobertura de skills'),('E01','Proyecto existente')]
options='<option value="" disabled>Ir a una rama…</option>'+''.join(f'<option value="{id}">{name}</option>' for id,name in bookmarks)
html=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Árbol de decisiones de diseño · v0.4</title><style>{css}</style></head><body>
<a class="skip" href="#main">Saltar al árbol</a><header><div class="eyebrow">REVISIÓN 0.4 · MY-SKILLS / EMIL / JAKUB</div><h1>Árbol de decisiones de diseño</h1><p>Explora las respuestas de cada pregunta. Las bifurcaciones representan alternativas; las aperturas de cobertura exigen revisar todos sus dominios. Los contextos existentes instancian las mismas definiciones, sin reconvergencias.</p><span class="status">Propuesta · aprobaciones humanas pendientes · no es un plugin ejecutable</span><details class="note"><summary>Qué cambió en v0.4</summary> identidad y cobertura separadas, dirección de arte explícita, microtipografía, medio siempre revisado, evaluación ligada a cada candidato y navegación real de ramas.</details></header>
<main id="main"><div class="toolbar"><label for="view">Acceso a una rama</label><select id="view">{options}</select><button id="root" type="button">Raíz</button><button id="up" type="button">Subir un nivel</button></div>
<form id="search-form"><label class="search-label" for="node-search">Ir a ID</label><input id="node-search" placeholder="ART01, E03, R05…" autocomplete="off"><button type="submit">Explorar nodo</button></form><p id="notice" class="caption" role="status" aria-live="polite"></p>
<div class="legend"><span><b class="or">DECISIÓN</b> una respuesta por requisito</span><span><b class="and">COBERTURA</b> todas las ramas</span></div>
<section class="view"><nav id="breadcrumbs" aria-label="Ruta del nodo"></nav><p id="branch-kind" class="eyebrow"></p><h2 id="branch-title" tabindex="-1"></h2><div class="toolbar"><button id="inspect-current" type="button">Ver ficha de esta pregunta</button><button id="zoom" type="button" aria-pressed="false">Alternar escala del diagrama</button></div><p class="caption">Los nodos enlazados abren sus respuestas. El diagrama muestra la pregunta y sus ramas inmediatas; el esquema inferior conserva toda la rama. El desplazamiento horizontal queda dentro del diagrama.</p><div class="canvas" id="canvas" tabindex="0" aria-label="Diagrama desplazable de la rama actual"></div></section>
<section class="inspector" id="inspect" aria-label="Ficha de decisión" hidden></section>
<section class="explorer"><h2>Esquema de la rama actual</h2><p class="caption">La profundidad no estrecha el texto. «Desplegar» sólo afecta la vista: no selecciona respuestas ni aprueba decisiones.</p><div class="toolbar"><button id="expand" type="button">Desplegar rama actual</button><button id="collapse" type="button">Plegar rama actual</button></div><ul id="outline" class="tree"></ul></section>
<section class="sources"><h2>Las 82 skills conservan una disposición visible</h2><p>No todas están incorporadas ni desarrolladas. Las asignaciones y exclusiones son propuestas; las capacidades condicionales requieren definir su rama antes de ejecutarlas.</p><div id="inventory"></div></section>
<section class="sources"><h2>Límites conocidos</h2><p>Las rutas nativas, gráficas y documentales especializadas siguen bloqueadas hasta detallar sus decisiones. La revisión por secciones no equivale a auditar todas las instrucciones de las 82 skills. Este visor no persiste aprobaciones ni impide acciones de un agente externo.</p><p>Los recursos del catálogo son candidatos, no dependencias instaladas. Las políticas locales están separadas de las recomendaciones de cada autor.</p></section>
<noscript><p>Este visor necesita JavaScript local para desplegar el árbol. El paquete incluye tree.json y el mapa de criterios como fuentes legibles. No hay dependencia de red.</p></noscript></main><footer>Fuente: árbol v0.3 conservado y criterios de la investigación. Versiones upstream fijadas en el inventario; no se afirma que coincidan con main actual. Registros de decisión propuestos, nunca autoaprobados.</footer>
<script id="source-data" type="application/json">{payload('tree.json')}</script><script id="rule-data" type="application/json">{payload('rules.json')}</script><script id="inventory-data" type="application/json">{payload('skill-inventory.json')}</script><script>{js}</script></body></html>'''
(P/'index.html').write_text(html)
print('HTML bytes',len(html.encode()),'sha256',hashlib.sha256(html.encode()).hexdigest())
